[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$TaskDirectory,[switch]$Adopt,[hashtable]$AdoptedPaths)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'PipelineProtocolV2.psm1') -Force;$state=Join-Path $TaskDirectory 'state.json';if(-not(Test-Path $state)){throw 'Task state not found'};$s=Get-Content -Raw $state|ConvertFrom-Json;if([int]$s.protocol_version -ge 2){return [pscustomobject]@{status='already_v2'}|ConvertTo-Json};if($s.status -in @('work','verify','review','awaiting_user_decision','awaiting_plan_approval','infrastructure_failed','manual_ui_required','deploy_pending','deploy')){throw 'Active v1 execution cannot be silently migrated'};if(-not $Adopt -or $null -eq $AdoptedPaths -or $AdoptedPaths.Count -eq 0){throw 'V1 migration requires explicit adopted paths and hashes'};if(-not(Test-Path (Join-Path $TaskDirectory 'request.raw.md')) -and (Test-Path (Join-Path $TaskDirectory 'request.md'))){Write-PipelineImmutableText (Join-Path $TaskDirectory 'request.legacy-interpreted.md') (Get-Content -Raw (Join-Path $TaskDirectory 'request.md'))|Out-Null};$s.protocol_version=2;$s.status='plan';$s.migration=[pscustomobject]@{from=1;at=[datetime]::UtcNow.ToString('o');mode='full_replan';adopted_paths=$AdoptedPaths};$out=Join-Path $TaskDirectory 'state.v2.json';Write-PipelineImmutableJson $out $s|Out-Null;[pscustomobject]@{status='migrated';path=$out;mode='full_replan'}|ConvertTo-Json
